Q: How to fetch the events from local calendar in iOS swift A: <p>First of all, don't forget to update your Info.plist with a NSCalendarsUsageDescription  by adding a new row:</p>
<ul>
<li><strong>Key:</strong> &quot;Privacy - Calendars Usage Description&quot;</li>
<li><strong>Value:</strong> &quot;Please give access&quot; - this is up to you</li>
</ul>
<p>Your ViewController should look similar to this:</p>
<pre><code>import UIKit
import EventKit

final class ViewController: UIViewController {
    let eventStore = EKEventStore()
    var titles: [String] = []
    var startDates: [Date] = []
    var endDates: [Date] = []

    override func viewDidLoad() {
        super.viewDidLoad()

        fetchEventsFromCalendar()
    }

    func fetchEventsFromCalendar() -&gt; Void {
        let status = EKEventStore.authorizationStatus(for: EKEntityType.event)
        switch status {
        case .notDetermined: requestAccessToCalendar(&quot;Calendar&quot;)
        case .authorized: fetchEventsFromCalendar(&quot;Calendar&quot;)
        case .denied: print(&quot;Access denied&quot;)
        default: break
        }
    }

    func requestAccessToCalendar(_ calendarTitle: String) {
        eventStore.requestAccess(to: EKEntityType.event) { (_, _) in
            self.fetchEventsFromCalendar(calendarTitle)
        }
    }

    func fetchEventsFromCalendar(_ calendarTitle: String) -&gt; Void {
        for calendar in eventStore.calendars(for: .event) {
            if calendar.title == calendarTitle {
                let oneMonthAgo = Calendar.current.date(byAdding: .month, value: -1, to: Date()) ?? Date()
                let oneMonthAfter = Calendar.current.date(byAdding: .month, value: 1, to: Date()) ?? Date()
                let predicate = eventStore.predicateForEvents(
                    withStart: oneMonthAgo,
                    end: oneMonthAfter,
                    calendars: [calendar]
                )
                let events = eventStore.events(matching: predicate)
                for event in events {
                    titles.append(event.title)
                    startDates.append(event.startDate as Date)
                    endDates.append(event.endDate as Date)
                }
            }
        }

        // Print the event titles so check if everything works correctly
        print(titles)
    }

}
</code></pre>
<p>You'll first check from Calendar access in <code>fetchEventsFromCalendar()</code>, and the actual event fetching will be handled in <code>fetchEventsFromCalendar()</code>.</p>
<p>One thing: in this particular example we're looking for events one month before and one month after toady in a calendar called <em>&quot;Calendar&quot;</em>. If you want to get the events for that period of time from all the calendars, you can simply remove the</p>
<pre><code>            if calendar.title == calendarTitle {
</code></pre>
<p>line (including the closing bracket and everything that has to do with <code>calendarTitle</code>). You'll have an array of all the events.</p>
